//! 📌️ A child checkpoint borrows the original authored metadata, skips clean history and captures one exact native pin in bounded turns.
use super::*;
use semio_os_kernel::os_vcs::{Author,CompositionPin,io::binary::checkpoint_identity::original::pending::OriginalPendingEditIds};
use semio_framework_artifact_reference::{ArtifactRef,ArtifactDialect};
use semio_framework_value::retained_clone::{RetainedCloneSource,RetainedCloneOwner,NativeAllocationIdentity};
use semio_framework_job::{OriginalConstructionAdmission,OriginalConstructionFailure};
use semio_framework_value::{RetainedCloneStep,OriginalRetirementFailure,RetainedWorkPoll,ValueError as Fault};
use semio_plugin_job_receiving::original_steps::{begin,born,forgotten,funds,paid,produced,replied,retired,settle,forward};
/// 🧾️ The parent's original authored metadata remains a unique source throughout its child cascade.
pub type CheckpointMetadata=(Option<String>,Vec<Author>);
/// 🪆️ A single live child owns its probe, copied request and exact VCS continuation until the resulting pin is taken.
pub struct ChildCheckpointUnit{binding:OriginalSourceBinding,decoder:(NativeAllocationIdentity,u64),frame:OriginalConstructionAdmission,failure:ManuallyDrop<Option<OriginalConstructionFailure>>,body:usize,probe:OriginalPendingEditIds,metadata:ManuallyDrop<Option<RetainedCloneOwner<CheckpointMetadata>>>,request:ManuallyDrop<Option<ArtifactNativeVcsRequest>>,command:ManuallyDrop<Option<Box<ChildVcsCommandUnit>>>,result:Option<ArtifactNativeVcsResult>,fields:ManuallyDrop<Option<[String;5]>>,pin:ManuallyDrop<Option<CompositionPin>>,retirement:RetainedCloneClose,field:usize,offset:usize,phase:u8,closing:bool}
impl ChildCheckpointUnit{
 pub fn capture_demands()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<Self>(),..header::<Self>()}}
 pub fn admit(cx:&mut StepContext<'_>,admission:&mut OriginalConstructionAdmission,failure:&mut Option<OriginalConstructionFailure>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let d=Self::capture_demands();born(cx,output,admission,failure,d,|native|Ok(Box::new(Self{binding,decoder:(native.ledger_identity(),native.retirement_recipient_identity().ok_or_else(invalid)?),frame:Default::default(),failure:ManuallyDrop::new(None),body,probe:OriginalPendingEditIds::probe(),metadata:ManuallyDrop::new(None),request:ManuallyDrop::new(None),command:ManuallyDrop::new(None),result:None,fields:ManuallyDrop::new(Some(Default::default())),pin:ManuallyDrop::new(None),retirement:Default::default(),field:0,offset:0,phase:0,closing:false})))}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 fn action(&mut self,cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(&mut Self)->Result<(),ValueError>)->Result<bool,OriginalTurnFailure>{if !funds(cx,d){return Ok(false)}run(self)?;paid(cx,d)?;Ok(true)}
 fn field<'a,M:SpaceMember>(&self,member:&'a M)->Result<&'a str,ValueError>{let identity=member.member_identity().ok_or_else(invalid)?;match self.field{0=>Ok(identity.artifact_id),1=>Ok(&identity.dialect.artifact_kind),2=>Ok(&identity.dialect.standard),3=>Ok(&identity.dialect.subset),4=>member.native_checkpoint_id().ok_or_else(invalid),_=>Err(invalid())}}
 pub fn next_construction_demands<M:SpaceMember>(&self,member:&M)->Option<RetirementDemand>{match self.phase{4=>Some(ChildVcsCommandUnit::capture_demands()),5=>self.command.as_ref().and_then(|c|c.next_construction_demands(member)),_=>None}}
 pub fn progress(&self)->(u8,Option<u8>){(self.phase,self.command.as_ref().map(|c|c.phase()))}
 pub fn ready(&self)->bool{self.phase==11&&!self.closing}
 pub fn advance<M:SpaceMember>(&mut self,member:&mut M,source:&RetainedCloneSource<CheckpointMetadata>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing||cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original child checkpoint was cancelled").into())}match self.phase{
 0=>{if let Some(dirty)=self.probe.pending_found(){self.action(cx,header::<u8>(),|s|{s.phase=if dirty{1}else{6};Ok(())})?;}else{let d=member.native_checkpoint_probe_demands(&self.probe)?;if funds(cx,d){let p=member.advance_native_checkpoint_probe(&mut self.probe,cx.retained_grant())?;cx.consume_retained(p)?;cx.consume_fuel(1)}}},
 1=>{let d=header::<RetainedCloneOwner<CheckpointMetadata>>();if produced(cx,d,&mut self.metadata,||Ok(RetainedCloneOwner::default()))?{self.phase=2;}},
 2=>{let owner=self.metadata.as_mut().ok_or_else(invalid)?;let view=source.try_borrow()?;let units=cx.fuel_remaining();let d=owner.advance_demands(view,self.body,units)?;let body=self.body;let mut finished=false;forward(cx,d,|effect|{let poll=replied::<OriginalRetirementFailure>(effect,|effect,reply|owner.advance_into(view,body,units,effect,reply));if let RetainedWorkPoll::Complete(turn)=&poll{finished=matches!(turn.result,Ok(RetainedCloneStep::Complete(_)))}poll})?;if finished{self.phase=3}},
 3=>{let owner=self.metadata.as_mut().ok_or_else(invalid)?;let d=owner.take_demand()?;let request=&mut self.request;let mut taken=false;forward(cx,d,|effect|replied::<Fault>(effect,|effect,reply|{let mut value=None;let done=owner.take(&mut value,effect,reply)?;if let Some((message,authors))=value{**request=Some(ArtifactNativeVcsRequest::CommitCheckpoint{message,authors});taken=true}Ok(done)}))?;if taken{self.phase=4}},
 4=>{if ChildVcsCommandUnit::admit(&mut self.request,cx,&mut self.frame,&mut self.failure,&mut self.command)?{self.phase=5;}},
 5=>{let owner=self.command.as_mut().ok_or_else(invalid)?;if !owner.ready(){owner.advance(member,cx)?;}else if owner.take_result(cx,&mut self.result)?{self.phase=6;}},
 6=>{if !self.close_children(member,cx)?{return Ok(false)}self.action(cx,header::<u8>(),|s|{s.phase=if member.native_checkpoint_id().is_some(){7}else{11};Ok(())})?;},
 7=>{let text=self.field(member)?;let d=RetirementDemand{capacity_bytes:text.len(),..header::<String>()};self.action(cx,d,|s|{let text=s.field(member)?;s.fields.as_mut().unwrap()[s.field].try_reserve_exact(text.len()).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original child checkpoint pin field reservation failed"))?;s.offset=0;s.phase=8;Ok(())})?;},
 8=>{let text=self.field(member)?;let mut end=(self.offset+64).min(text.len());while !text.is_char_boundary(end){end-=1;}let d=RetirementDemand{copy_bytes:end-self.offset+size_of::<(usize,u8)>(),depth:1,..Default::default()};self.action(cx,d,|s|{s.fields.as_mut().unwrap()[s.field].push_str(&text[s.offset..end]);s.offset=end;if end==text.len(){s.field+=1;s.phase=if s.field==5{9}else{7};}Ok(())})?;},
 9=>{self.action(cx,header::<(CompositionPin,Option<[String;5]>,u8)>(),|s|{let[artifact_id,artifact_kind,standard,subset,checkpoint_id]=s.fields.take().ok_or_else(invalid)?;*s.pin=Some(CompositionPin{child_ref:ArtifactRef{artifact_id,dialect:ArtifactDialect{artifact_kind,standard,subset}},checkpoint_id});s.phase=10;Ok(())})?;},
 10=>{self.action(cx,header::<u8>(),|s|{s.phase=11;Ok(())})?;},11=>{},_=>return Err(invalid().into()),}Ok(self.ready())}
 pub fn take_pin(&mut self,cx:&mut StepContext<'_>,output:&mut Option<(bool,Option<CompositionPin>)>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.ready(){return Err(invalid().into())}let d=header::<(bool,Option<CompositionPin>,u8)>();if produced(cx,d,output,||Ok((self.result.is_some(),self.pin.take())))?{self.phase=12;return Ok(true)}Ok(false)}
 fn close_children<M:SpaceMember>(&mut self,member:&mut M,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  let body=self.body;
  if let Some(owner)=self.command.as_mut(){if !owner.terminal_is_empty(){cx.with_original_retirement(|cx|owner.close_step(member,cx))?;return Ok(false)}let mut d=ChildVcsCommandUnit::release_demands();d.copy_bytes=size_of::<Option<Box<ChildVcsCommandUnit>>>();forgotten(cx,d,||{self.command.take();})?;return Ok(false)}
  if !self.retirement.is_empty()&&self.metadata.is_none(){let d=self.retirement.demands(body)?;retired(cx,d,|effect|self.retirement.step_granted(effect.grant().maximum_copy_bytes,effect))?;return Ok(false)}
  if self.metadata.is_some(){let d=self.retirement.next_owner_demands::<RetainedCloneOwner<CheckpointMetadata>>(true,&None,body)?;retired(cx,d,|effect|begin(&mut self.retirement,&mut self.metadata,effect))?;return Ok(false)}
  if !self.probe.terminal_is_empty(){let d=self.probe.close_demands(body)?;retired(cx,d,|effect|{let turn=self.probe.close_step(effect);settle(effect,turn)})?;return Ok(false)}
  if self.failure.is_some(){let d=self.retirement.next_owner_demands::<OriginalConstructionFailure>(true,&None,body)?;retired(cx,d,|effect|begin(&mut self.retirement,&mut self.failure,effect))?;return Ok(false)}
  if !self.frame.terminal_is_empty(){self.frame.close_step(cx)?;return Ok(false)}
  Ok(true)
 }
 pub fn close_demands<M:SpaceMember>(&self,member:&M)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(header::<bool>())}if let Some(owner)=self.command.as_ref(){if owner.terminal_is_empty(){return Ok(RetirementDemand{copy_bytes:size_of::<Option<Box<ChildVcsCommandUnit>>>(),..ChildVcsCommandUnit::release_demands()})}return owner.close_demands(member)}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.metadata.is_some(){return self.retirement.next_owner_demands::<RetainedCloneOwner<CheckpointMetadata>>(true,&None,self.body)}if !self.probe.terminal_is_empty(){return self.probe.close_demands(self.body)}if self.failure.is_some(){return self.retirement.next_owner_demands::<OriginalConstructionFailure>(true,&None,self.body)}if self.request.is_some(){return self.retirement.next_owner_demands::<ArtifactNativeVcsRequest>(true,&None,self.body)}if self.fields.is_some(){return self.retirement.next_owner_demands::<[String;5]>(true,&None,self.body)}if self.pin.is_some(){return self.retirement.next_owner_demands::<CompositionPin>(true,&None,self.body)}if self.result.is_some(){return Ok(header::<Option<ArtifactNativeVcsResult>>())}Ok(Default::default())}
 pub fn close_step<M:SpaceMember>(&mut self,member:&mut M,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.terminal_is_empty(){return Ok(true)}let d=self.close_demands(member)?;if !self.closing{if funds(cx,d){self.closing=true;paid(cx,d)?}return Ok(false)}if !self.close_children(member,cx)?{return Ok(false)}
  if !self.retirement.is_empty()||self.request.is_some()||self.fields.is_some()||self.pin.is_some(){retired(cx,d,|effect|{if !self.retirement.is_empty(){return begin(&mut self.retirement,&mut self.pin,effect)}if self.request.is_some(){return begin(&mut self.retirement,&mut self.request,effect)}if self.fields.is_some(){return begin(&mut self.retirement,&mut self.fields,effect)}begin(&mut self.retirement,&mut self.pin,effect)})?;return Ok(false)}
  if self.result.is_some(){forgotten(cx,d,||{self.result=None;})?;return Ok(false)}
  Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.failure.is_none()&&self.frame.terminal_is_empty()&&self.probe.terminal_is_empty()&&self.metadata.is_none()&&self.request.is_none()&&self.command.is_none()&&self.fields.is_none()&&self.pin.is_none()&&self.result.is_none()&&self.retirement.is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for ChildCheckpointUnit{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original child checkpoint requires funded closure")}}

